def localize_text(value):
    text=str(value)
    if translation.get_language()!="fj": return text
    if text in PHRASES: return PHRASES[text]
    if text in CHOICES: return CHOICES[text]
    result=" ".join(WORDS.get(word.lower(),word) for word in text.split())
    return result[:1].upper()+result[1:] if result else result

def localize_form(form):
    for field in form.fields.values():
        field.label=localize_text(field.label)
        if isinstance(field.widget, forms.CheckboxInput):
            field.widget.attrs.setdefault("class", "h-5 w-5 rounded border-slate-300 text-teal-700 focus:ring-teal-700")
        else:
            field.widget.attrs.setdefault("class", "w-full rounded border border-slate-300 p-2 focus:border-teal-700 focus:ring-teal-700")
        if isinstance(field.widget, forms.DateInput): field.widget.input_type="date"
        if isinstance(field.widget, forms.DateTimeInput): field.widget.input_type="datetime-local"
        if isinstance(field,forms.ChoiceField) and not isinstance(field,forms.ModelChoiceField):
            field.choices=[(value,localize_text(label)) for value,label in field.choices]
    return form
